mapper.sql:
t.deleted = 0

    AND (
        t.prisoner_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR t.prisoner_number LIKE CONCAT('%', #{q.keyword}, '%')
        OR t.from_area_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR t.to_area_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR t.from_cell_number LIKE CONCAT('%', #{q.keyword}, '%')
        OR t.to_cell_number LIKE CONCAT('%', #{q.keyword}, '%')
    )


    AND t.prisoner_id = #{q.prisonerId}


    AND t.from_area_id = #{q.fromAreaId}


    AND t.to_area_id = #{q.toAreaId}


    AND t.from_cell_id = #{q.fromCellId}


    AND t.to_cell_id = #{q.toCellId}


    AND t.transfer_type = #{q.transferType}


    AND t.transfer_time >= #{q.startTime}


    AND t.transfer_time <= #{q.endTime}
